kit_prompt_prefix:
Create a multiplayer browser game as a SINGLE HTML file (public/index.html). The file has a template with lobby HTML, net.js (networking), and audio.js already loaded. Your game code goes in the LAST <script> block.

NETWORKING IS ALREADY DONE — net.js provides: myId, myName, myColor, remotePlayers (object of other players' positions), remoteEvents (other players' actions), LEFT()/RIGHT()/UP()/DOWN()/ACTION() input helpers, emitGameEvent(type,data), GameAudio.play(name). You MUST define getMyState() returning {x,y,score,state}. You MUST render ALL remotePlayers entries alongside your local player using the SAME draw functions. DO NOT create socket connections. DO NOT write socket.on listeners. DO NOT write lobby code.

STRUCTURE: 1) Canvas 480x700, requestAnimationFrame loop. 2) Movement via LEFT()/RIGHT()/UP()/DOWN(). 3) Shooting/action via ACTION() + emitGameEvent('shoot',{x,y,dir}). 4) Audio: GameAudio.play('shoot'|'explode'|'hit'|'collect'|'lose'|'jump'|'coin'|'powerup'|'bounce'). NEVER create AudioContext. 5) 2-3 local AI bots. 6) Game over overlay. 7) HUD with scores.

RENDERING REMOTE PLAYERS: In your game loop, iterate remotePlayers: for(var pid in remotePlayers){var rp=remotePlayers[pid]; drawPlayer(ctx,rp.x,rp.y,rp.extra.color);} Use the same sprite functions for remote and local players.

=== SPRITE DRAWING QUALITY — CRITICAL ===
NEVER draw entities as plain rectangles or single triangles. Every sprite MUST be a detailed multi-part composition using 10+ Canvas 2D draw calls. Use ctx.save()/ctx.restore(), ctx.translate(), ctx.rotate(), ctx.arc(), ctx.beginPath()/ctx.lineTo()/ctx.closePath(), ctx.createRadialGradient(), ctx.shadowBlur/ctx.shadowColor for glow.

EXAMPLE — How to draw a GORILLA (not a rectangle!):
function drawGorilla(ctx,x,y){
  ctx.save();ctx.translate(x,y);
  // Brown fur body
  ctx.fillStyle='#5C3317';ctx.beginPath();ctx.ellipse(0,0,22,28,0,0,Math.PI*2);ctx.fill();
  // Chest
  ctx.fillStyle='#8B6914';ctx.beginPath();ctx.ellipse(0,5,14,16,0,0,Math.PI*2);ctx.fill();
  // Head
  ctx.fillStyle='#5C3317';ctx.beginPath();ctx.arc(0,-26,14,0,Math.PI*2);ctx.fill();
  // Face
  ctx.fillStyle='#D2A06D';ctx.beginPath();ctx.ellipse(0,-24,9,10,0,0,Math.PI*2);ctx.fill();
  // Eyes
  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-5,-27,3,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(5,-27,3,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#000';ctx.beginPath();ctx.arc(-4,-27,1.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(6,-27,1.5,0,Math.PI*2);ctx.fill();
  // Nostrils
  ctx.fillStyle='#4A2A0A';ctx.beginPath();ctx.arc(-2,-21,1.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(2,-21,1.5,0,Math.PI*2);ctx.fill();
  // Mouth
  ctx.strokeStyle='#4A2A0A';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-19,4,0.1*Math.PI,0.9*Math.PI);ctx.stroke();
  // Arms
  ctx.fillStyle='#5C3317';ctx.beginPath();ctx.ellipse(-26,2,8,18,0.3,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(26,2,8,18,-0.3,0,Math.PI*2);ctx.fill();
  // Hands
  ctx.fillStyle='#4A2A0A';ctx.beginPath();ctx.arc(-28,18,6,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(28,18,6,0,Math.PI*2);ctx.fill();
  // Legs
  ctx.fillStyle='#5C3317';ctx.beginPath();ctx.ellipse(-10,28,8,10,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(10,28,8,10,0,0,Math.PI*2);ctx.fill();
  ctx.restore();
}

EXAMPLE — How to draw a JET FIGHTER (not a triangle!):
function drawJet(ctx,x,y,color){
  ctx.save();ctx.translate(x,y);
  // Fuselage
  ctx.fillStyle=color||'#4488FF';
  ctx.beginPath();ctx.moveTo(0,-18);ctx.bezierCurveTo(-5,-10,-6,10,-4,18);ctx.lineTo(4,18);ctx.bezierCurveTo(6,10,5,-10,0,-18);ctx.fill();
  // Cockpit canopy
  var cg=ctx.createRadialGradient(0,-8,1,0,-8,5);cg.addColorStop(0,'#aef');cg.addColorStop(1,'#258');ctx.fillStyle=cg;ctx.beginPath();ctx.ellipse(0,-8,4,6,0,0,Math.PI*2);ctx.fill();
  // Wings
  ctx.fillStyle=color||'#4488FF';ctx.beginPath();ctx.moveTo(-5,2);ctx.lineTo(-22,12);ctx.lineTo(-18,14);ctx.lineTo(-5,8);ctx.fill();
  ctx.beginPath();ctx.moveTo(5,2);ctx.lineTo(22,12);ctx.lineTo(18,14);ctx.lineTo(5,8);ctx.fill();
  // Tail fins
  ctx.beginPath();ctx.moveTo(-3,15);ctx.lineTo(-10,20);ctx.lineTo(-3,18);ctx.fill();
  ctx.beginPath();ctx.moveTo(3,15);ctx.lineTo(10,20);ctx.lineTo(3,18);ctx.fill();
  // Engine glow
  ctx.shadowBlur=8;ctx.shadowColor='#f80';
  ctx.fillStyle='#fa0';ctx.fillRect(-2,17,4,4+Math.random()*4);
  ctx.fillStyle='#ff6';ctx.fillRect(-1,17,2,3+Math.random()*3);
  ctx.shadowBlur=0;
  ctx.restore();
}

EXAMPLE — How to draw a CAR (not a rectangle!):
function drawCar(ctx,x,y,color){
  ctx.save();ctx.translate(x,y);
  // Shadow
  ctx.fillStyle='rgba(0,0,0,0.3)';ctx.beginPath();ctx.ellipse(0,2,16,8,0,0,Math.PI*2);ctx.fill();
  // Body
  ctx.fillStyle=color||'#e22';ctx.beginPath();ctx.roundRect(-14,-10,28,24,4);ctx.fill();
  // Roof/cabin
  ctx.fillStyle=color?'#'+Math.min(0xff,parseInt(color.slice(1,3),16)+0x33).toString(16)+color.slice(3):'#f55';ctx.beginPath();ctx.roundRect(-10,-6,20,12,3);ctx.fill();
  // Windshield
  ctx.fillStyle='#adf';ctx.beginPath();ctx.roundRect(-8,-5,16,5,2);ctx.fill();
  // Headlights
  ctx.fillStyle='#ff4';ctx.shadowBlur=4;ctx.shadowColor='#ff4';ctx.beginPath();ctx.arc(-10,-10,2.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(10,-10,2.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
  // Taillights
  ctx.fillStyle='#f22';ctx.beginPath();ctx.arc(-10,13,2,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(10,13,2,0,Math.PI*2);ctx.fill();
  // Wheels
  ctx.fillStyle='#222';ctx.fillRect(-16,-4,4,6);ctx.fillRect(12,-4,4,6);ctx.fillRect(-16,6,4,6);ctx.fillRect(12,6,4,6);
  ctx.restore();
}

EXAMPLE — How to draw a HUMAN/PERSON:
function drawPerson(ctx,x,y,color,frame){
  ctx.save();ctx.translate(x,y);
  // Legs (animated walk)
  var legSwing=Math.sin(frame*0.15)*4;
  ctx.fillStyle='#36c';ctx.fillRect(-4,8,4,12+legSwing);ctx.fillRect(2,8,4,12-legSwing);
  // Shoes
  ctx.fillStyle='#333';ctx.fillRect(-5,19+legSwing,6,3);ctx.fillRect(1,19-legSwing,6,3);
  // Body/torso
  ctx.fillStyle=color||'#e44';ctx.beginPath();ctx.roundRect(-7,-4,14,14,2);ctx.fill();
  // Arms (animated)
  ctx.fillStyle='#da8';ctx.fillRect(-10,0,4,10-legSwing);ctx.fillRect(8,0,4,10+legSwing);
  // Head
  ctx.fillStyle='#da8';ctx.beginPath();ctx.arc(0,-10,7,0,Math.PI*2);ctx.fill();
  // Hair
  ctx.fillStyle='#421';ctx.beginPath();ctx.arc(0,-13,7,Math.PI,2*Math.PI);ctx.fill();
  // Eyes
  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-3,-11,2,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(3,-11,2,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#000';ctx.beginPath();ctx.arc(-2.5,-11,1,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(3.5,-11,1,0,Math.PI*2);ctx.fill();
  // Smile
  ctx.strokeStyle='#a55';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,-8,3,0.1*Math.PI,0.9*Math.PI);ctx.stroke();
  ctx.restore();
}

